def get_item(item_id: int, skip: int = 0, limit: int = 10):
    return {"item_id": item_id, "skip": skip, "limit": limit}


def resolve_path_params(func, raw_path_values):
    annotations = func.__annotations__
    converted = {}
    for name, raw in raw_path_values.items():
        expected_type = annotations.get(name, str)
        try:
            converted[name] = expected_type(raw)
        except ValueError:
            return None, {"status": 422, "error": f"invalid type for {name!r}"}
    return converted, None


def call_route(func, raw_path_values, query_values):
    path_args, error = resolve_path_params(func, raw_path_values)
    if error:
        return error
    kwargs = dict(path_args)
    for key, value in query_values.items():
        kwargs[key] = int(value)
    return {"status": 200, "data": func(**kwargs)}


print(call_route(get_item, {"item_id": "42"}, {"skip": "0", "limit": "10"}))
print(call_route(get_item, {"item_id": "7"}, {}))
print(call_route(get_item, {"item_id": "abc"}, {}))
